<script setup>
import {ref,reactive} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,validateField,updateAccount} from '../store'
const router=useRouter(),editing=ref(false),confirm=ref(false),notice=ref(''),errors=reactive({}),form=reactive({...state.profile}),avatar=ref('')
const fields=[['name','Họ và tên'],['studentId','Mã sinh viên'],['birth','Ngày sinh','date'],['gender','Giới tính'],['school','Trường đại học'],['major','Ngành học'],['phone','Số điện thoại','tel'],['zalo','Số điện thoại Zalo','tel'],['email','Email','email'],['address','Địa chỉ']]
function save(){Object.keys(errors).forEach(k=>delete errors[k]);for(const k of ['name','email','phone','zalo']){const e=validateField(k,form[k]);if(e)errors[k]=e}if(!Object.keys(errors).length)confirm.value=true}
async function commit(){try{await updateAccount(form);editing.value=false;confirm.value=false;notice.value='Đã lưu thông tin cá nhân.'}catch(error){confirm.value=false;notice.value=error.message;if(error.field)errors[error.field]=error.message}}
function upload(e){const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){notice.value='Chọn ảnh JPG, PNG, WEBP tối đa 10 MB.';return}if(avatar.value)URL.revokeObjectURL(avatar.value);avatar.value=URL.createObjectURL(f)}
</script>
<template><div v-if="!state.user" class="container empty-state"><span class="empty-icon"><Icon name="user" :size="40"/></span><h1>Không gian của riêng bạn</h1><p>Đăng nhập để xem hồ sơ và quản lý bài đăng.</p><RouterLink to="/dang-nhap?redirect=/ho-so" class="button primary">Đăng nhập <Icon name="arrow" :size="18"/></RouterLink></div><div v-else class="container page profile-page"><div class="section-heading"><div><span class="eyebrow">Tài khoản của bạn</span><h1>Thông tin cá nhân</h1></div><button v-if="!editing" class="button secondary" @click="editing=true;notice=''"><Icon name="edit" :size="17"/>Chỉnh sửa</button></div><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="profile-layout"><aside class="profile-summary"><div class="profile-avatar"><img v-if="avatar" :src="avatar" alt="Ảnh đại diện"><span v-else>{{state.profile.name.split(' ').map(s=>s[0]).slice(-2).join('')}}</span><label v-if="editing" class="avatar-edit"><Icon name="camera" :size="18"/><input type="file" accept="image/jpeg,image/png,image/webp" @change="upload" aria-label="Đổi ảnh đại diện"></label></div><h2>{{state.profile.name}}</h2><p class="muted">{{state.user.role==='landlord'?'Chủ trọ':'Sinh viên'}} · {{state.profile.school}}</p><nav class="profile-links"><RouterLink to="/ho-so"><Icon name="user" :size="18"/>Thông tin cá nhân</RouterLink><RouterLink to="/quan-ly/bai-dang"><Icon name="grid" :size="18"/>Quản lý bài đăng</RouterLink><RouterLink v-if="state.user.role==='landlord'" to="/quan-ly/nha-tro"><Icon name="building" :size="18"/>Quản lý nhà trọ</RouterLink></nav></aside><form class="form-panel" @submit.prevent="save"><div class="form-grid"><label v-for="[key,label,type] in fields" :key="key" class="field"><span>{{label}}</span><select v-if="key==='gender'" v-model="form[key]" :disabled="!editing"><option>Nam</option><option>Nữ</option><option>Khác</option></select><input v-else v-model.trim="form[key]" :type="type||'text'" :disabled="!editing" :aria-invalid="!!errors[key]"><small class="error" v-if="errors[key]">{{errors[key]}}</small></label><label class="field span-two"><span>Giới thiệu bản thân</span><textarea v-model="form.bio" :disabled="!editing" rows="4" placeholder="Chia sẻ đôi chút về bạn và thói quen sống…"></textarea></label></div><div v-if="editing" class="form-actions"><button type="button" class="button secondary" @click="Object.assign(form,state.profile);editing=false">Hủy</button><button class="button primary">Lưu thay đổi <Icon name="check" :size="18"/></button></div></form></div><Teleport to="body"><div v-if="confirm" class="modal-backdrop" @click.self="confirm=false" @keydown.esc="confirm=false"><section class="modal" v-dialog-focus role="dialog" aria-modal="true" aria-labelledby="profile-confirm"><span class="empty-icon"><Icon name="check" :size="28"/></span><h2 id="profile-confirm">Lưu thay đổi?</h2><p>Thông tin cá nhân của bạn sẽ được cập nhật trên thiết bị này.</p><div class="form-actions"><button class="button secondary" @click="confirm=false">Quay lại</button><button class="button primary" @click="commit">Xác nhận lưu</button></div></section></div></Teleport></div></template>
